using System;using System.IO;using System.Drawing;using System.Globalization;using System.Windows.Forms;
namespace ScoreModern {
 public sealed partial class Editor {
  Color? workspaceColor;
  string WorkspaceSettingsPath{get{return "workspace";}}
  void AddBackgroundMenu(ContextMenuStrip menu){try{int value;if(!Program.CheckMode&&NativeSettings.Exists(WorkspaceSettingsPath)&&Int32.TryParse(NativeSettings.ReadAllText(WorkspaceSettingsPath),out value))workspaceColor=Color.FromArgb(value);}catch(IOException){}catch(UnauthorizedAccessException){}var item=new ToolStripMenuItem("Non-page background colour...");item.Click+=(s,e)=>{using(var picker=new ColorDialog{Color=workspaceColor??viewport.BackColor,FullOpen=true})if(picker.ShowDialog(this)==DialogResult.OK){workspaceColor=picker.Color;NativeSettings.WriteAllText(WorkspaceSettingsPath,picker.Color.ToArgb().ToString(CultureInfo.InvariantCulture));ApplyPreferenceColors();}};menu.Items.Add(item);var usePalette=new ToolStripMenuItem("Use COLO for non-page background"); usePalette.Click+=(s,e)=>Safe(()=>{NativeSettings.WriteAllText(WorkspaceSettingsPath,"palette");workspaceColor=null;ApplyPreferenceColors();});menu.Items.Add(usePalette);menu.Opening+=(s,e)=>usePalette.Checked=!workspaceColor.HasValue;ApplyPreferenceColors();}
  static string WindowSettingsPath{get{return "window";}}
  void RestoreWindowSettings(){if(Program.CheckMode)return;try{if(!NativeSettings.Exists(WindowSettingsPath))return;string[] fields=NativeSettings.ReadAllText(WindowSettingsPath).Split(',');if(fields.Length!=5)return;int x,y,w,h;if(!Int32.TryParse(fields[0],out x)||!Int32.TryParse(fields[1],out y)||!Int32.TryParse(fields[2],out w)||!Int32.TryParse(fields[3],out h)||w<200||h<200)return;Rectangle area=Screen.FromRectangle(new Rectangle(x,y,w,h)).WorkingArea;w=Math.Min(area.Width,Math.Max(MinimumSize.Width,w));h=Math.Min(area.Height,Math.Max(MinimumSize.Height,h));StartPosition=FormStartPosition.Manual;Bounds=new Rectangle(Math.Max(area.Left,Math.Min(x,area.Right-w)),Math.Max(area.Top,Math.Min(y,area.Bottom-h)),w,h);if(fields[4]=="maximized")WindowState=FormWindowState.Maximized;}catch(IOException){}catch(UnauthorizedAccessException){}}
  void SaveWindowSettings(){if(Program.CheckMode)return;Rectangle b=WindowState==FormWindowState.Normal?Bounds:RestoreBounds;try{NativeSettings.WriteAllText(WindowSettingsPath,String.Join(",",new[]{b.X.ToString(CultureInfo.InvariantCulture),b.Y.ToString(CultureInfo.InvariantCulture),b.Width.ToString(CultureInfo.InvariantCulture),b.Height.ToString(CultureInfo.InvariantCulture),WindowState==FormWindowState.Maximized?"maximized":"normal"}));}catch(IOException){}catch(UnauthorizedAccessException){}}
 }
}
